fn is_prime(n: i8) -> bool {
    // Primality is only defined for integers >= 2
    if n < 2 {
        return false;
    }

    // We will check all potential divisors k from 2 up to n - 1
    // Invariants maintained throughout the loop:
    // - n >= 2
    // - current candidate divisor k is in [2, n]
    // - for all previously checked j with 2 <= j < k, n % j != 0

    let mut k = 2;
    while k < n {
        // If n is divisible by k, it is not prime
        if n % k == 0 {
            return false;
        }
        // Increase k, the termination measure (n - k) strictly decreases each iteration
        k += 1;
    }

    // No divisors found means n is prime
    true
}